-- models/marts/fct_daily_revenue.sql
{{ config(materialized='incremental', unique_key='revenue_date') }}

with charges as (
    select * from {{ ref('stg_charges') }}
    {% if is_incremental() %}
      where created_at >= (select max(revenue_date) from {{ this }})
    {% endif %}
)

select
    cast(created_at as date)        as revenue_date,
    currency,
    sum(amount_usd)                 as total_revenue,
    count(charge_id)                as charge_count
from charges
where is_paid = true
group by 1, 2
